root = os.path.join(os.path.dirname(__file__), '../../../src/i18n/strings')
tables = {l: json.load(open(os.path.join(root, f'{l}.json'))) for l in LANGS}
for key, vals in S.items():
    assert len(vals) == len(LANGS), key
    for l, v in zip(LANGS, vals):
        tables[l][key] = v
en = tables['en']
for q, a in FAQ:
    assert len(q) == len(LANGS) and len(a) == len(LANGS)
    qk = [k for k in en if k.startswith('faq_') and k.endswith('_q') and en[k] == q[0]]
    assert len(qk) == 1, (q[0], qk)
    ak = qk[0][:-2] + '_a'
    assert en[ak] == a[0], ak
    for i, l in enumerate(LANGS):
        tables[l][qk[0]] = q[i]
        tables[l][ak] = a[i]
for l in LANGS:
    p = os.path.join(root, f'{l}.json')
    json.dump(tables[l], open(p, 'w'), ensure_ascii=False, indent=2)
    open(p, 'a').write('\n')
print(len(S) + 2 * len(FAQ), 'strings in', len(LANGS), 'languages')
